     8	import br.com.marealta.pousada.domain.AppException;
     9	import br.com.marealta.pousada.domain.ErrorCode;
    10	import br.com.marealta.pousada.domain.RatePlan;
    11	import br.com.marealta.pousada.service.ReportService;
    12	import br.com.marealta.pousada.service.ReservationService;
    13	import br.com.marealta.pousada.service.ReservationService.NewReservation;
    14	import io.javalin.Javalin;
    15	import io.javalin.http.Context;
    16	import java.time.LocalDate;
    17	import java.time.YearMonth;
    18	import java.time.format.DateTimeParseException;
    19	import java.util.Map;
    20	import org.slf4j.Logger;
    21	import org.slf4j.LoggerFactory;
    22	
    23	public final class Api {
    24	    private static final Logger LOG = LoggerFactory.getLogger(Api.class);
    25	    private static final ObjectMapper JSON = new ObjectMapper()
    26	            .registerModule(new JavaTimeModule())
    27	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    28	            .enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN);
    29	
    30	    private final ReservationService reservations;
    31	    private final ReportService reports;
    32	
    33	    public Api(ReservationService reservations, ReportService reports) {
    34	        this.reservations = reservations;
    35	        this.reports = reports;
    36	    }
    37	
    38	    public Javalin create() {
    39	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
    40	
    41	        app.get("/rooms", ctx -> json(ctx, 200, reservations.rooms()));
    42	        app.post("/reservations", ctx -> json(ctx, 201, reservations.create(parseNewReservation(ctx))));
    43	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservations.get(id(ctx))));
    44	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, reservations.confirm(id(ctx))));
    45	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, reservations.cancel(id(ctx))));
    46	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, reservations.checkIn(id(ctx))));
    47	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, reservations.checkOut(id(ctx))));
    48	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, reservations.document(id(ctx))));
    49	        app.get("/messages", ctx -> json(ctx, 200, reservations.messages()));
    50	        app.get("/reports/occupancy", ctx -> csv(ctx, reports.occupancy(date(ctx.queryParam("date"), "date"))));
    51	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(month(ctx.queryParam("month")))));
    52	
    53	        app.exception(AppException.class, (e, ctx) -> error(ctx, e.code(), e.getMessage()));
    54	        app.exception(Exception.class, (e, ctx) -> {
    55	            LOG.error("Erro inesperado", e);
    56	            ctx.status(500).contentType("application/json")
    57	                    .result("{\"error\":\"INTERNAL_ERROR\",\"message\":\"Erro interno\"}");
    58	        });
    59	        return app;
    60	    }
    61	
    62	    private static void error(Context ctx, ErrorCode code, String message) {
    63	        json(ctx, code.httpStatus(), Map.of("error", code.name(), "message", message));
    64	    }
    65	
    66	    private static void json(Context ctx, int status, Object body) {
    67	        try {
    68	            ctx.status(status).contentType("application/json").result(JSON.writeValueAsString(body));
    69	        } catch (JsonProcessingException e) {
    70	            throw new IllegalStateException(e);
    71	        }
    72	    }
    73	
    74	    private static void csv(Context ctx, String body) {
    75	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
    76	    }
    77	
    78	    private static long id(Context ctx) {
    79	        try {
    80	            return Long.parseLong(ctx.pathParam("id"));
    81	        } catch (NumberFormatException e) {
    82	            throw new AppException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + ctx.pathParam("id") + " não existe");
    83	        }
    84	    }
    85	
    86	    private static LocalDate date(String value, String field) {
    87	        if (value == null) {
    88	            throw invalid("Falta o parâmetro " + field);
    89	        }
    90	        try {
    91	            return LocalDate.parse(value);
    92	        } catch (DateTimeParseException e) {
    93	            throw invalid("Data inválida em " + field + ": use o formato 2027-07-10");
    94	        }
    95	    }
    96	
    97	    private static YearMonth month(String value) {
    98	        if (value == null) {
    99	            throw invalid("Falta o parâmetro month");
   100	        }
   101	        try {
   102	            return YearMonth.parse(value);
   103	        } catch (DateTimeParseException e) {
   104	            throw invalid("Mês inválido: use o formato 2027-07");
   105	        }
   106	    }
   107	
   108	    private static NewReservation parseNewReservation(Context ctx) {
   109	        JsonNode body;
   110	        try {
   111	            body = JSON.readTree(ctx.body());
   112	        } catch (JsonProcessingException e) {
   113	            throw invalid("O corpo não é um JSON válido");
   114	        }
   115	        if (body == null || !body.isObject()) {
   116	            throw invalid("O corpo deve ser um objeto JSON");
   117	        }
   118	        LocalDate checkIn = date(text(body, "checkIn"), "checkIn");
   119	        LocalDate checkOut = date(text(body, "checkOut"), "checkOut");
   120	        int guests = integer(body, "guests");
   121	        int roomNumber = integer(body, "roomNumber");
   122	        String guestName = text(body, "guestName");
   123	        String guestEmail = text(body, "guestEmail");
   124	        String guestCpf = text(body, "guestCpf");
   125	        RatePlan plan;
   126	        try {
   127	            plan = RatePlan.valueOf(text(body, "ratePlan"));
   128	        } catch (IllegalArgumentException e) {
   129	            throw invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE");
   130	        }
   131	        if (!checkOut.isAfter(checkIn)) {
   132	            throw invalid("A saída deve ser depois da entrada");
   133	        }
   134	        if (guests < 1) {
   135	            throw invalid("Deve haver ao menos um hóspede");
   136	        }
   137	        return new NewReservation(roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, plan);
   138	    }
   139	
   140	    private static String text(JsonNode body, String field) {
   141	        JsonNode n = body.get(field);
   142	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
   143	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
   144	        }
   145	        return n.asText();
   146	    }
   147	
   148	    private static int integer(JsonNode body, String field) {
   149	        JsonNode n = body.get(field);
   150	        if (n == null || !n.isIntegralNumber() || !n.canConvertToInt()) {
   151	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
   152	        }
   153	        return n.intValue();
   154	    }
   155	
   156	    private static AppException invalid(String message) {
   157	        return new AppException(ErrorCode.INVALID_REQUEST, message);
   158	    }
   159	}
