     1	package br.com.marealta.pousada.service;
     2	
     3	import br.com.marealta.pousada.domain.AppException;
     4	import br.com.marealta.pousada.domain.ErrorCode;
     5	import br.com.marealta.pousada.domain.Message;
     6	import br.com.marealta.pousada.domain.RatePlan;
     7	import br.com.marealta.pousada.domain.Receipt;
     8	import br.com.marealta.pousada.domain.Reservation;
     9	import br.com.marealta.pousada.domain.ReservationStatus;
    10	import br.com.marealta.pousada.domain.Room;
    11	import br.com.marealta.pousada.events.NotificationRule;
    12	import br.com.marealta.pousada.events.ReservationEvent;
    13	import br.com.marealta.pousada.persistence.Database;
    14	import br.com.marealta.pousada.persistence.Tx;
    15	import java.time.LocalDate;
    16	import java.util.List;
    17	import java.util.function.UnaryOperator;
    18	
    19	public class ReservationService {
    20	
    21	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    22	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    23	    }
    24	
    25	    private final Database db;
    26	    private final List<NotificationRule> rules;
    27	
    28	    public ReservationService(Database db, List<NotificationRule> rules) {
    29	        this.db = db;
    30	        this.rules = List.copyOf(rules);
    31	    }
    32	
    33	    public List<Room> rooms() {
    34	        return db.inTransaction(tx -> tx.rooms().findAll());
    35	    }
    36	
    37	    public List<Message> messages() {
    38	        return db.inTransaction(tx -> tx.messages().findAll());
    39	    }
    40	
    41	    public Reservation get(long id) {
    42	        return db.inTransaction(tx -> tx.reservations().find(id).orElseThrow(() -> notFound(id)));
    43	    }
    44	
    45	    public Reservation create(NewReservation n) {
    46	        return db.inTransaction(tx -> {
    47	            Room room = tx.rooms().findForUpdate(n.roomNumber())
    48	                    .orElseThrow(() -> new AppException(ErrorCode.ROOM_NOT_FOUND, "Quarto " + n.roomNumber() + " não existe"));
    49	            if (n.guests() > room.capacity()) {
    50	                throw new AppException(ErrorCode.CAPACITY_EXCEEDED,
    51	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    52	            }
    53	            if (tx.reservations().hasOverlap(room.number(), n.checkIn(), n.checkOut())) {
    54	                throw new AppException(ErrorCode.ROOM_UNAVAILABLE,
    55	                        "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    56	            }
    57	            return tx.reservations().insert(Reservation.pending(room, n.guestName(), n.guestEmail(), n.guestCpf(),
    58	                    n.checkIn(), n.checkOut(), n.guests(), n.ratePlan()));
    59	        });
    60	    }
    61	
    62	    public Reservation confirm(long id) {
    63	        return transition(id, Reservation::confirm);
    64	    }
    65	
    66	    public Reservation cancel(long id) {
    67	        return transition(id, Reservation::cancel);
    68	    }
    69	
    70	    public Reservation checkIn(long id) {
    71	        return transition(id, Reservation::startStay);
    72	    }
    73	
    74	    public Receipt checkOut(long id) {
    75	        return db.inTransaction(tx -> {
    76	            Reservation r = lock(tx, id).endStay();
    77	            tx.reservations().update(r);
    78	            return Receipt.of(r, room(tx, r));
    79	        });
    80	    }
    81	
    82	    /** Segunda via do comprovante; só existe para reserva paga. */
    83	    public Receipt document(long id) {
    84	        return db.inTransaction(tx -> {
    85	            Reservation r = tx.reservations().find(id).orElseThrow(() -> notFound(id));
    86	            if (!r.paid()) {
    87	                throw new AppException(ErrorCode.OPERATION_NOT_ALLOWED,
    88	                        "A reserva " + id + " está " + r.status() + " e não tem comprovante");
    89	            }
    90	            return Receipt.of(r, room(tx, r));
    91	        });
    92	    }
    93	
    94	    private Reservation transition(long id, UnaryOperator<Reservation> change) {
    95	        return db.inTransaction(tx -> {
    96	            Reservation before = lock(tx, id);
    97	            Reservation after = change.apply(before);
    98	            tx.reservations().update(after);
    99	            Room room = room(tx, after);
   100	            ReservationEvent event = switch (after.status()) {
   101	                case CONFIRMED -> new ReservationEvent.Confirmed(after, room);
   102	                case CANCELLED -> new ReservationEvent.Cancelled(after, room,
   103	                        before.status() == ReservationStatus.CONFIRMED);
   104	                default -> null;
   105	            };
   106	            if (event != null) {
   107	                publish(tx, event);
   108	            }
   109	            return after;
   110	        });
   111	    }
   112	
   113	    private void publish(Tx tx, ReservationEvent event) {
   114	        for (NotificationRule rule : rules) {
   115	            rule.messagesFor(event).forEach(tx.messages()::add);
   116	        }
   117	    }
   118	
   119	    private static Reservation lock(Tx tx, long id) {
   120	        return tx.reservations().findForUpdate(id).orElseThrow(() -> notFound(id));
   121	    }
   122	
   123	    private static Room room(Tx tx, Reservation r) {
   124	        return tx.rooms().find(r.roomNumber()).orElseThrow();
   125	    }
   126	
   127	    private static AppException notFound(long id) {
   128	        return new AppException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe");
   129	    }
   130	}
