     6	import java.util.List;
     7	
     8	/** Financeiro: quanto entrou na confirmação e quanto precisa ser devolvido no cancelamento. */
     9	public class FinanceNotifications implements NotificationRule {
    10	    private final String address;
    11	
    12	    public FinanceNotifications(String address) {
    13	        this.address = address;
    14	    }
    15	
    16	    @Override
