    23	    public String occupancy(LocalDate night) {
    24	        return db.inTransaction(tx -> {
    25	            Map<Integer, RoomType> types = tx.rooms().findAll().stream()
    26	                    .collect(Collectors.toMap(Room::number, Room::type));
    27	            List<Reservation> occupying = tx.reservations().findPaidOccupying(night);
    28	            StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    29	            for (Reservation r : occupying) {
    30	                csv.append(r.roomNumber()).append(',').append(types.get(r.roomNumber())).append(',')
    31	                        .append(r.id()).append(',').append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    32	            }
    33	            long occupied = occupying.stream().map(Reservation::roomNumber).distinct().count();
    34	            return csv.append("total,").append(occupied).append('/').append(types.size()).append('\n').toString();
    35	        });
    36	    }
    37	
    38	    public String revenue(YearMonth month) {
    39	        return db.inTransaction(tx -> {
    40	            List<Reservation> list = tx.reservations()
    41	                    .findKeepingMoneyStartingBetween(month.atDay(1), month.plusMonths(1).atDay(1));
    42	            StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    43	            BigDecimal total = Money.ZERO;
