    25	    private final Database db;
    26	    private final List<NotificationRule> rules;
    27	
    28	    public ReservationService(Database db, List<NotificationRule> rules) {
    29	        this.db = db;
    30	        this.rules = List.copyOf(rules);
    31	    }
    32	
    33	    public List<Room> rooms() {
    34	        return db.inTransaction(tx -> tx.rooms().findAll());
    35	    }
