    45	    public Reservation create(NewReservation n) {
    46	        return db.inTransaction(tx -> {
    47	            Room room = tx.rooms().findForUpdate(n.roomNumber())
    48	                    .orElseThrow(() -> new AppException(ErrorCode.ROOM_NOT_FOUND, "Quarto " + n.roomNumber() + " não existe"));
    49	            if (n.guests() > room.capacity()) {
    50	                throw new AppException(ErrorCode.CAPACITY_EXCEEDED,
    51	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    52	            }
    53	            if (tx.reservations().hasOverlap(room.number(), n.checkIn(), n.checkOut())) {
    54	                throw new AppException(ErrorCode.ROOM_UNAVAILABLE,
    55	                        "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    56	            }
    57	            return tx.reservations().insert(Reservation.pending(room, n.guestName(), n.guestEmail(), n.guestCpf(),
    58	                    n.checkIn(), n.checkOut(), n.guests(), n.ratePlan()));
