    70	    public Reservation checkIn(long id) {
    71	        return transition(id, Reservation::startStay);
    72	    }
    73	
    74	    public Receipt checkOut(long id) {
    75	        return db.inTransaction(tx -> {
    76	            Reservation r = lock(tx, id).endStay();
    77	            tx.reservations().update(r);
    78	            return Receipt.of(r, room(tx, r));
    79	        });
    80	    }
    81	
    82	    /** Segunda via do comprovante; só existe para reserva paga. */
    83	    public Receipt document(long id) {
    84	        return db.inTransaction(tx -> {
    85	            Reservation r = tx.reservations().find(id).orElseThrow(() -> notFound(id));
    86	            if (!r.paid()) {
    87	                throw new AppException(ErrorCode.OPERATION_NOT_ALLOWED,
    88	                        "A reserva " + id + " está " + r.status() + " e não tem comprovante");
    89	            }
    90	            return Receipt.of(r, room(tx, r));
    91	        });
    92	    }
    93	
    94	    private Reservation transition(long id, UnaryOperator<Reservation> change) {
    95	        return db.inTransaction(tx -> {
    96	            Reservation before = lock(tx, id);
    97	            Reservation after = change.apply(before);
    98	            tx.reservations().update(after);
    99	            Room room = room(tx, after);
   100	            ReservationEvent event = switch (after.status()) {
   101	                case CONFIRMED -> new ReservationEvent.Confirmed(after, room);
   102	                case CANCELLED -> new ReservationEvent.Cancelled(after, room,
   103	                        before.status() == ReservationStatus.CONFIRMED);
   104	                default -> null;
   105	            };
   106	            if (event != null) {
   107	                publish(tx, event);
   108	            }
   109	            return after;
   110	        });
   111	    }
   112	
   113	    private void publish(Tx tx, ReservationEvent event) {
   114	        for (NotificationRule rule : rules) {
   115	            rule.messagesFor(event).forEach(tx.messages()::add);
   116	        }
   117	    }
   118	
   119	    private static Reservation lock(Tx tx, long id) {
   120	        return tx.reservations().findForUpdate(id).orElseThrow(() -> notFound(id));
   121	    }
