    16	    public Database(String url, String user, String password, String schema) {
    17	        HikariConfig cfg = new HikariConfig();
    18	        cfg.setJdbcUrl(url);
    19	        cfg.setUsername(user);
    20	        cfg.setPassword(password);
    21	        cfg.setMaximumPoolSize(10);
    22	        cfg.setInitializationFailTimeout(30_000);
    23	        if (schema != null) {
    24	            cfg.setSchema(schema);
    25	        }
    26	        this.dataSource = new HikariDataSource(cfg);
    27	    }
    28	
    29	    /** Cria o que falta no banco e grava os quartos. */
    30	    public void migrate() {
    31	        inTransaction(tx -> {
    32	            try (Statement st = tx.connection().createStatement()) {
    33	                st.execute("SELECT pg_advisory_xact_lock(727001)");
    34	                st.execute("""
    35	                        CREATE TABLE IF NOT EXISTS rooms (
    36	                            number INTEGER PRIMARY KEY,
    37	                            type VARCHAR(20) NOT NULL,
    38	                            capacity INTEGER NOT NULL,
    39	                            nightly_rate NUMERIC(12,2) NOT NULL)""");
    40	                st.execute("""
    41	                        CREATE TABLE IF NOT EXISTS reservations (
    42	                            id BIGSERIAL PRIMARY KEY,
    43	                            room_number INTEGER NOT NULL REFERENCES rooms(number),
    44	                            guest_name TEXT NOT NULL,
    45	                            guest_email TEXT NOT NULL,
    46	                            guest_cpf TEXT NOT NULL,
    47	                            check_in DATE NOT NULL,
    48	                            check_out DATE NOT NULL,
    49	                            guests INTEGER NOT NULL,
    50	                            rate_plan VARCHAR(20) NOT NULL,
    51	                            nights INTEGER NOT NULL,
    52	                            subtotal NUMERIC(12,2) NOT NULL,
    53	                            discount NUMERIC(12,2) NOT NULL,
    54	                            total NUMERIC(12,2) NOT NULL,
    55	                            status VARCHAR(20) NOT NULL,
    56	                            amount_paid NUMERIC(12,2) NOT NULL,
    57	                            refund NUMERIC(12,2))""");
    58	                st.execute("CREATE INDEX IF NOT EXISTS reservations_room_dates ON reservations (room_number, check_in, check_out)");
    59	                st.execute("""
    60	                        CREATE TABLE IF NOT EXISTS messages (
    61	                            id BIGSERIAL PRIMARY KEY,
    62	                            channel VARCHAR(20) NOT NULL,
    63	                            recipient TEXT NOT NULL,
    64	                            subject TEXT NOT NULL,
    65	                            body TEXT NOT NULL)""");
    66	            } catch (SQLException e) {
    67	                throw new IllegalStateException(e);
    68	            }
    69	            for (Room room : Room.ALL) {
    70	                tx.rooms().insertIfAbsent(room);
    71	            }
    72	            return null;
    73	        });
    74	    }
    75	
    76	    public <T> T inTransaction(Function<Tx, T> work) {
    77	        try (Connection c = dataSource.getConnection()) {
    78	            c.setAutoCommit(false);
    79	            try {
    80	                T result = work.apply(new Tx(c));
    81	                c.commit();
    82	                return result;
    83	            } catch (RuntimeException | Error e) {
    84	                c.rollback();
    85	                throw e;
    86	            }
    87	        } catch (SQLException e) {
    88	            throw new IllegalStateException("Erro de banco de dados", e);
    89	        }
    90	    }
