     1	package br.com.marealta.pousada.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	import java.time.temporal.ChronoUnit;
     7	
     8	public record Pricing(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     9	    private static final BigDecimal PEAK_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    11	
    12	    public static Pricing quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    13	        BigDecimal subtotal = Money.ZERO;
    14	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    15	            subtotal = subtotal.add(nightPrice(room, night));
    16	        }
    17	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    18	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
    19	                : Money.ZERO;
    20	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    21	        return new Pricing(nights, subtotal, discount, subtotal.subtract(discount));
    22	    }
    23	
    24	    static BigDecimal nightPrice(Room room, LocalDate night) {
    25	        BigDecimal rate = Money.round(room.nightlyRate());
    26	        return isHighSeason(night) ? Money.round(rate.multiply(PEAK_MULTIPLIER)) : rate;
    27	    }
    28	
    29	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    30	    static boolean isHighSeason(LocalDate night) {
    31	        Month month = night.getMonth();
    32	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    33	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    34	    }
    35	}
