     5	
     6	public record Reservation(
     7	        Long id,
     8	        int roomNumber,
     9	        String guestName,
    10	        String guestEmail,
    11	        String guestCpf,
    12	        LocalDate checkIn,
    13	        LocalDate checkOut,
    14	        int guests,
    15	        RatePlan ratePlan,
    16	        int nights,
    17	        BigDecimal subtotal,
    18	        BigDecimal discount,
    19	        BigDecimal total,
    20	        ReservationStatus status,
    21	        BigDecimal amountPaid,
    22	        BigDecimal refund) {
    23	
    24	    public static Reservation pending(Room room, String guestName, String guestEmail, String guestCpf,
    25	                                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    26	        Pricing p = Pricing.quote(room, checkIn, checkOut, ratePlan);
    27	        return new Reservation(null, room.number(), guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    28	                ratePlan, p.nights(), p.subtotal(), p.discount(), p.total(), ReservationStatus.PENDING,
    29	                Money.ZERO, null);
    30	    }
    31	
    32	    public Reservation confirm() {
    33	        requireStatus("confirmada", ReservationStatus.PENDING);
    34	        return copy(ReservationStatus.CONFIRMED, total, refund);
    35	    }
    36	
    37	    public Reservation startStay() {
    38	        requireStatus("feito o check-in", ReservationStatus.CONFIRMED);
    39	        return copy(ReservationStatus.CHECKED_IN, amountPaid, refund);
    40	    }
    41	
    42	    public Reservation endStay() {
    43	        requireStatus("feito o check-out", ReservationStatus.CHECKED_IN);
    44	        return copy(ReservationStatus.CHECKED_OUT, amountPaid, refund);
    45	    }
    46	
    47	    public Reservation cancel() {
    48	        requireStatus("cancelada", ReservationStatus.PENDING, ReservationStatus.CONFIRMED);
    49	        BigDecimal toRefund = ratePlan == RatePlan.STANDARD ? amountPaid : Money.ZERO;
    50	        return copy(ReservationStatus.CANCELLED, amountPaid, toRefund);
    51	    }
    52	
    53	    /** Reserva paga (confirmada, com check-in ou com check-out). */
    54	    public boolean paid() {
    55	        return status == ReservationStatus.CONFIRMED || status == ReservationStatus.CHECKED_IN
    56	                || status == ReservationStatus.CHECKED_OUT;
    57	    }
    58	
    59	    /** O que ficou com a pousada: pago menos devolvido. */
    60	    public BigDecimal kept() {
    61	        return refund == null ? amountPaid : amountPaid.subtract(refund);
    62	    }
    63	
    64	    public Reservation withId(long newId) {
    65	        return new Reservation(newId, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    66	                ratePlan, nights, subtotal, discount, total, status, amountPaid, refund);
    67	    }
    68	
    69	    private Reservation copy(ReservationStatus newStatus, BigDecimal newPaid, BigDecimal newRefund) {
    70	        return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    71	                ratePlan, nights, subtotal, discount, total, newStatus, newPaid, newRefund);
    72	    }
    73	
    74	    private void requireStatus(String action, ReservationStatus... allowed) {
    75	        for (ReservationStatus s : allowed) {
    76	            if (s == status) {
    77	                return;
    78	            }
    79	        }
    80	        throw new AppException(ErrorCode.OPERATION_NOT_ALLOWED,
    81	                "A reserva " + id + " está " + status + " e não pode ser " + action);
    82	    }
