 32	    @BeforeAll
 33	    static void start() throws Exception {
 34	        String url = System.getenv("DB_URL");
 35	        assumeTrue(url != null, "DB_URL não definida");
 36	        schema = "test_" + UUID.randomUUID().toString().replace("-", "");
 37	        try (Connection c = DriverManager.getConnection(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 38	             Statement st = c.createStatement()) {
 39	            st.execute("CREATE SCHEMA " + schema);
 40	        } catch (Exception e) {
 41	            schema = null;
 42	            assumeTrue(false, "Banco inacessível: " + e.getMessage());
 43	        }
 44	        db = new Database(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"), schema);
 45	        app = Main.createApp(db).start(0);
 46	        base = "http://localhost:" + app.port();
 47	    }
 48	
 49	    @AfterAll
 50	    static void stop() throws Exception {
 51	        if (app != null) {
 52	            app.stop();
 53	        }
 54	        if (db != null) {
 55	            db.close();
 56	        }
 57	        if (schema != null) {
 58	            try (Connection c = DriverManager.getConnection(System.getenv("DB_URL"), System.getenv("DB_USER"),
 59	                    System.getenv("DB_PASSWORD")); Statement st = c.createStatement()) {
 60	                st.execute("DROP SCHEMA " + schema + " CASCADE");
 61	            }
 62	        }
 63	    }
 64	
 65	    private static HttpResponse<String> call(String method, String path, String body) throws Exception {
 66	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
 67	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 68	        return HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString());
 69	    }
