 97	        assertError(call("POST", "/reservations", "nope"), 400, "INVALID_REQUEST");
 98	        assertError(call("POST", "/reservations", booking(101, "2027-03-12", "2027-03-12", 1, "STANDARD")), 400, "INVALID_REQUEST");
 99	        assertError(call("POST", "/reservations", booking(101, "2027-03-10", "2027-03-12", 0, "STANDARD")), 400, "INVALID_REQUEST");
100	        assertError(call("POST", "/reservations", booking(999, "2027-03-10", "2027-03-12", 1, "STANDARD")), 404, "ROOM_NOT_FOUND");
101	        assertError(call("POST", "/reservations", booking(102, "2027-03-10", "2027-03-12", 3, "STANDARD")), 422, "CAPACITY_EXCEEDED");
102	        assertError(call("GET", "/reservations/99999", null), 404, "RESERVATION_NOT_FOUND");
103	
104	        JsonNode first = create(102, "2028-03-10", "2028-03-12", 2, "STANDARD");
105	        assertEquals("PENDING", first.get("status").asText());
106	        assertEquals(499.80, first.get("total").asDouble());
107	        assertTrue(first.get("refund").isNull());
108	        assertError(call("POST", "/reservations", booking(102, "2028-03-11", "2028-03-13", 1, "STANDARD")), 409, "ROOM_UNAVAILABLE");
109	        // saída no dia da entrada de outra reserva é permitido
110	        create(102, "2028-03-12", "2028-03-14", 1, "STANDARD");
111	        // cancelada libera o quarto
112	        long id = first.get("id").asLong();
113	        assertEquals(200, call("POST", "/reservations/" + id + "/cancellation", null).statusCode());
114	        create(102, "2028-03-10", "2028-03-12", 1, "STANDARD");
