117	    @Test
118	    void lifecycleNotificationsAndReports() throws Exception {
119	        int before = JSON.readTree(call("GET", "/messages", null).body()).size();
120	        JsonNode r = create(201, "2029-03-10", "2029-03-12", 2, "STANDARD");
121	        long id = r.get("id").asLong();
122	        String path = "/reservations/" + id;
123	
124	        assertError(call("GET", path + "/document", null), 409, "OPERATION_NOT_ALLOWED");
125	        assertError(call("POST", path + "/check-in", null), 409, "OPERATION_NOT_ALLOWED");
126	        // cancelar pendente não avisa ninguém
127	        JsonNode other = create(202, "2029-03-10", "2029-03-12", 2, "STANDARD");
128	        call("POST", "/reservations/" + other.get("id").asLong() + "/cancellation", null);
129	        assertEquals(before, JSON.readTree(call("GET", "/messages", null).body()).size());
130	
131	        JsonNode confirmed = JSON.readTree(call("POST", path + "/confirmation", null).body());
132	        assertEquals("CONFIRMED", confirmed.get("status").asText());
133	        assertEquals(779.80, confirmed.get("amountPaid").asDouble());
134	        assertError(call("POST", path + "/confirmation", null), 409, "OPERATION_NOT_ALLOWED");
135	
136	        JsonNode msgs = JSON.readTree(call("GET", "/messages", null).body());
137	        assertEquals(before + 3, msgs.size());
138	        String all = msgs.toString();
139	        assertTrue(all.contains("Reserva confirmada - Pousada Maré Alta"));
140	        assertTrue(all.contains("Reserva confirmada - quarto 201"));
141	        assertTrue(all.contains("Pagamento recebido - reserva " + id));
142	        assertTrue(all.contains("governanca@pousadamarealta.com.br"));
143	        assertTrue(all.contains("financeiro@pousadamarealta.com.br"));
144	
145	        String csv = call("GET", "/reports/occupancy?date=2029-03-11", null).body();
146	        assertTrue(csv.startsWith("room,type,reservation,check_in,check_out\n"), csv);
147	        assertTrue(csv.contains("201,DELUXE," + id + ",2029-03-10,2029-03-12\n"), csv);
148	        assertEquals(0, call("GET", "/reports/occupancy?date=2029-03-12", null).body().indexOf("room,"));
149	        assertTrue(call("GET", "/reports/occupancy?date=2029-03-12", null).body().contains("total,0/5"));
150	        assertError(call("GET", "/reports/occupancy?date=xx", null), 400, "INVALID_REQUEST");
151	
152	        assertEquals(200, call("POST", path + "/check-in", null).statusCode());
153	        assertError(call("POST", path + "/cancellation", null), 409, "OPERATION_NOT_ALLOWED");
154	        HttpResponse<String> out = call("POST", path + "/check-out", null);
155	        assertEquals(200, out.statusCode());
156	        JsonNode doc = JSON.readTree(out.body());
157	        assertEquals("Comprovante de reserva", doc.get("title").asText());
158	        assertEquals("DELUXE", doc.get("roomType").asText());
159	        assertEquals(doc, JSON.readTree(call("GET", path + "/document", null).body()));
160	
161	        String revenue = call("GET", "/reports/revenue?month=2029-03", null).body();
162	        assertTrue(revenue.contains(id + ",201,2029-03-10,2029-03-12,CHECKED_OUT,779.80\n"), revenue);
163	        assertError(call("GET", "/reports/revenue?month=2029-3", null), 400, "INVALID_REQUEST");
164	    }
