166	    @Test
167	    void cancellationOfPaidReservations() throws Exception {
168	        // plano normal: devolve tudo e avisa governança e financeiro
169	        long a = create(301, "2030-03-10", "2030-03-11", 4, "STANDARD").get("id").asLong();
170	        call("POST", "/reservations/" + a + "/confirmation", null);
171	        int before = JSON.readTree(call("GET", "/messages", null).body()).size();
172	        JsonNode cancelled = JSON.readTree(call("POST", "/reservations/" + a + "/cancellation", null).body());
173	        assertEquals("CANCELLED", cancelled.get("status").asText());
174	        assertEquals(579.90, cancelled.get("refund").asDouble());
