179	        assertTrue(msgs.contains("R$ 579,90"));
180	
181	        // não reembolsável: nada a devolver, só a governança é avisada, e o valor continua no financeiro
182	        long b = create(301, "2030-04-10", "2030-04-11", 1, "NON_REFUNDABLE").get("id").asLong();
183	        JsonNode conf = JSON.readTree(call("POST", "/reservations/" + b + "/confirmation", null).body());
184	        assertEquals(492.92, conf.get("total").asDouble());
